contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256[] calldata winners) public payable {
        require(c.isAdmin(address(this)), "test must be admin");

        // The caller must be an admin to call pickWinner successfully.
        // Make the test contract an admin before invoking pickWinner.
        c.adjustAdminAccess(address(this), true);

        uint256 roundIdBefore = c.roundId();
        uint256 winnersPerPeriodBefore = c.winnersPerPeriod();
        require(winners.length == winnersPerPeriodBefore, "winners length mismatch");
        require(!c.isSelectionComplete(roundIdBefore), "selection already complete");

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.roundId() == roundIdBefore + 1);
            assert(c.isSelectionComplete(roundIdBefore));
        } else {
            assert(c.roundId() == roundIdBefore);
        }
    }
}

