contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 tokenId0, uint256 points0, uint256 tokenId1, uint256 points1) public {
        require(tokenId0 != tokenId1, "need distinct fighters");
        require(points0 <= 1000, "points0 bounded");
        require(points1 <= 1000, "points1 bounded");

        c.adjustAdminAccess(address(this), true);
        c.updateWinnersPerPeriod(2);

        uint256 preTotalPoints = c.totalPoints();

        uint256[] memory winners = new uint256[](2);
        winners[0] = tokenId0;
        winners[1] = tokenId1;

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.fighterPoints(tokenId0) == 0 && c.fighterPoints(tokenId1) == 0);
        } else {
            assert(c.fighterPoints(tokenId0) == 0 && c.fighterPoints(tokenId1) == 0);
        }
    }
}

