contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 tokenId0, uint256 tokenId1) public {
        require(tokenId0 != tokenId1, "need distinct fighters");

        c.adjustAdminAccess(address(this), true);
        c.updateWinnersPerPeriod(2);

        uint256 p0Before = c.fighterPoints(tokenId0);
        uint256 p1Before = c.fighterPoints(tokenId1);
        uint256 totalBefore = c.totalPoints();

        uint256[] memory winners = new uint256[](2);
        winners[0] = tokenId0;
        winners[1] = tokenId1;

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: on success, selected fighters' points are cleared and totalPoints
        // drops by exactly the sum of the selected fighters' pre-call points.
        assert(
            reverted ||
            (c.fighterPoints(tokenId0) == 0 &&
             c.fighterPoints(tokenId1) == 0 &&
             c.totalPoints() == totalBefore - p0Before - p1Before)
        );
    }
}

