contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256[] calldata winners) public payable {
        require(winners.length == c.winnersPerPeriod(), "winners must equal winnersPerPeriod");
        require(!c.isSelectionComplete(c.roundId()), "round already selected");

        uint256 roundBefore = c.roundId();

        c.pickWinner(winners);

        bool allComplete = true;
        for (uint256 r = 0; r <= roundBefore; r++) {
            if (!c.isSelectionComplete(r)) {
                allComplete = false;
                break;
            }
        }
        assert(allComplete);
    }

    receive() external payable {}
}

