contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address adminAddress, bool access) public payable {
        // caller is the address that will attempt adjustAdminAccess.
        // We cannot spoof msg.sender, so we test from this contract's address.
        // The rule: if this contract is not the owner, the call must revert;
        // and any successful call must make isAdmin[adminAddress] == access.
        //
        // Read the owner-visible admin state before the call.
        bool before = c.isAdmin(adminAddress);

        bool reverted;
        try c.adjustAdminAccess(adminAddress, access) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool after = c.isAdmin(adminAddress);

        // General rule: a call to adjustAdminAccess either reverts (and then
        // the admin flag for adminAddress must be unchanged), or it succeeds
        // (and then the flag must equal the requested `access` value).
        assert((reverted && after == before) || (!reverted && after == access));
    }

    receive() external payable {}
}

