contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 winnerId0, uint256 winnerId1, uint256 newWinnersPerPeriod) public {
        // Ensure the caller is an admin so pickWinner does not revert on access control.
        // The test contract is deployed by the same deployer as c, but we cannot rely on
        // msg.sender in c being the deployer, so set ourselves as admin first.
        c.adjustAdminAccess(address(this), true);

        // Set the number of winners per period to exactly 2 for this run.
        c.updateWinnersPerPeriod(newWinnersPerPeriod);
        uint256 wpp = c.winnersPerPeriod();
        require(wpp == newWinnersPerPeriod, "winnersPerPeriod not set as requested");

        // Only proceed when exactly 2 winners are needed, so the supplied ids match the requirement.
        require(wpp == 2, "test requires winnersPerPeriod == 2");

        // Read the current round id before the call.
        uint256 oldRoundId = c.roundId();
        bool before = c.isSelectionComplete(oldRoundId);
        require(!before, "round already selection-complete before call");

        uint256[] memory winners = new uint256[](2);
        winners[0] = winnerId0;
        winners[1] = winnerId1;

        // Admin call to pick winners for the current round.
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call succeeded, isSelectionComplete must be true for the round that was current before the call.
        bool after = c.isSelectionComplete(oldRoundId);
        assert(!reverted ? after == true : after == before);
    }
}

