contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address claimer, address admin, uint256[] calldata winners, uint256 numToClaim) public payable {
        require(admin != address(0), "admin zero");
        require(claimer != address(0), "claimer zero");

        // Drive c to a known baseline: caller has not claimed any round.
        uint32 baseline = c.numRoundsClaimed(claimer);

        // Make the contract owner an admin so pickWinner can be exercised when needed.
        c.adjustAdminAccess(admin, true);

        // Record the before-state of getUnclaimedRewards for the same caller.
        uint256 beforeRewards = c.getUnclaimedRewards(claimer);

        // Pick winners only if the caller supplied exactly the expected number of winners.
        if (winners.length == c.winnersPerPeriod()) {
            // This call changes c's state and must be a top-level statement.
            c.pickWinner(winners);
        }

        // Read the observable reward count after the state change attempt.
        uint256 afterRewards = c.getUnclaimedRewards(claimer);

        // Claim if the caller has any observed unclaimed rewards and supplied enough URIs.
        bool claimed = false;
        if (afterRewards > 0 && numToClaim > 0) {
            string[] memory modelURIs = new string[](numToClaim);
            string[] memory modelTypes = new string[](numToClaim);
            uint256[2][] memory customAttributes = new uint256[2][](numToClaim);
            for (uint256 i = 0; i < numToClaim; i++) {
                modelURIs[i] = "ipfs://test";
                modelTypes[i] = "test";
                customAttributes[i][0] = 0;
                customAttributes[i][1] = 0;
            }
            c.claimRewards(modelURIs, modelTypes, customAttributes);
            claimed = true;
        }

        // General rule: getUnclaimedRewards must never return a value larger than the
        // number of rounds finalized since the caller's recorded claim index, because
        // each such round can award at most one reward to the caller.
        // Also, completing claimRewards must not increase the unclaimed reward count.
        uint256 roundsFinalizedSinceBaseline = c.roundId() - baseline;
        assert(afterRewards <= roundsFinalizedSinceBaseline && (!claimed || c.getUnclaimedRewards(claimer) <= afterRewards));
    }

    receive() external payable {}
}

