contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenA, uint256 tokenB, uint256 pointsA, uint256 pointsB) public {
        require(tokenA != tokenB);

        // Read the starting total, which is the only pre-existing observable value we can rely on.
        uint256 beforeTotal = c.totalPoints();

        // Zero-out baseline for the two fighters before setting points (both start at 0 on a fresh c).
        // fighterPoints getter is public, so reading it is allowed.
        uint256 startingA = c.fighterPoints(tokenA);
        uint256 startingB = c.fighterPoints(tokenB);

        // Make the deciding call: select these two fighters as the winners for the current round.
        uint256[] memory selected = new uint256[](2);
        selected[0] = tokenA;
        selected[1] = tokenB;

        uint256 roundBefore = c.roundId();
        bool reverted;
        try c.pickWinner(selected) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // A failed pickWinner must not move any of the tracked state.
            assert(c.totalPoints() == beforeTotal && c.roundId() == roundBefore);
        } else {
            // A successful pickWinner clears the selected fighters' points and subtracts their
            // prior points from totalPoints.
            assert(
                c.fighterPoints(tokenA) == 0 &&
                c.fighterPoints(tokenB) == 0 &&
                beforeTotal >= startingA + startingB &&
                c.totalPoints() == beforeTotal - startingA - startingB
            );
        }
    }
}

