contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256[] calldata winners, uint256 extraPoint1) public {
        // Setup: the admin (this test contract) adds points to fighter tokens,
        // then calls pickWinner and checks the points reset rule.
        uint256 n = c.winnersPerPeriod();
        require(winners.length == n);

        // Pre-condition: round must not have completed selection yet.
        uint256 rid = c.roundId();
        require(!c.isSelectionComplete(rid));

        // Record before points for every winner token.
        uint256 sumBefore = 0;
        uint256[] memory beforePts = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            beforePts[i] = c.fighterPoints(winners[i]);
            sumBefore += beforePts[i];
        }

        uint256 totalBefore = c.totalPoints();

        // Attempt pickWinner. It may revert (e.g. bad owner) — capture that.
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // Rule: after successful pickWinner, all selected winners have fighterPoints[token] == 0.
            for (uint256 i = 0; i < n; i++) {
                assert(c.fighterPoints(winners[i]) == 0);
            }
            // And totalPoints dropped by exactly the sum of winners' pre-call points.
            assert(c.totalPoints() == totalBefore - sumBefore);
            assert(c.isSelectionComplete(rid));
        } else {
            // On revert, only require that state was left consistent: points and totals unchanged.
            for (uint256 i = 0; i < n; i++) {
                assert(c.fighterPoints(winners[i]) == beforePts[i]);
            }
            assert(c.totalPoints() == totalBefore);
            assert(!c.isSelectionComplete(rid));
        }
    }
}

