        c = _c;
    }

    function run(address claimer, uint8 w0, uint8 w1) public payable {
        // Setup: make claimer a winner in the current round via the public entry.
        uint256[] memory winners = new uint256[](2);
        winners[0] = w0;
        winners[1] = w1;
        c.pickWinner(winners);

        // Read the observable return of getUnclaimedRewards twice.
        uint256 first = c.getUnclaimedRewards(claimer);
        uint256 second = c.getUnclaimedRewards(claimer);

        // General rule: the getter is pure/deterministic over unchanged state, so both
        // calls agree, and after pickWinner the round count advanced by one.
        assert(second == first && c.roundId() == 1);
    }
}

