contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256[] calldata winners) public payable {
        require(winners.length == c.winnersPerPeriod(), "winners length mismatch");

        uint256 beforeRoundId = c.roundId();
        require(!c.isSelectionComplete(beforeRoundId), "selection already complete before call");

        bool[] memory wasComplete = new bool[](winners.length);
        for (uint256 i = 0; i < winners.length; i++) {
            wasComplete[i] = c.isSelectionComplete(beforeRoundId);
        }

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 afterRoundId = c.roundId();
            assert(afterRoundId == beforeRoundId + 1);
            assert(c.isSelectionComplete(beforeRoundId));
            for (uint256 i = 0; i < winners.length; i++) {
                assert(c.fighterPoints(winners[i]) == 0);
            }
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

