contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 key, uint256[] calldata winners) public {
        // The caller (this test contract) must be an admin of c.
        // Setup: this contract is the owner and isAdmin set at construction, but we check it first.
        require(c.isAdmin(address(this)));

        // If the key already has selection complete, pickWinner must revert.
        if (c.isSelectionComplete(key)) {
            (bool ok, ) = address(c).call(
                abi.encodeWithSignature("pickWinner(uint256[])", winners)
            );
            require(!ok);
        } else {
            // Need to satisfy: winners.length == winnersPerPeriod; adjust if necessary.
            uint256 wp = c.winnersPerPeriod();
            if (winners.length == wp) {
                c.pickWinner(winners);
                assert(c.isSelectionComplete(key));
            } else {
                // Not the right size: must revert.
                (bool ok, ) = address(c).call(
                    abi.encodeWithSignature("pickWinner(uint256[])", winners)
                );
                require(!ok);
            }
        }
    }
}

